-- Схема 26: друга книга обліку — посуд одноразового використання, миючі засоби й серветки
-- («книга ОП») — і форма 2/Прод цілком.
--
-- Позиція належить книзі своєї групи: групи розділів 21/Прод — книга ТЗ, групи ОП — книга
-- ОП. Статус документа у ФЕС і поля документів книги ОП (рапорт, наказ, скан, графа 2/прод)
-- — окремі таблиці 1:1 з документом. Перелік 2/Прод — рядки бланка А2788 за номером рядка:
-- однакові назви в бланку трапляються, тож унікальність — за номером, а не за назвою.
-- Перебудова таблиць іде з вимкненими зовнішніми ключами (так велить SQLite для зміни
-- обмежень; PRAGMA діє лише поза транзакцією, тому тіло — між BEGIN і COMMIT після неї).
-- Ключі перевіряє тест (PRAGMA foreign_key_check).

PRAGMA foreign_keys = OFF;
BEGIN;

ALTER TABLE nomen_group ADD COLUMN book TEXT NOT NULL DEFAULT 'ТЗ' CHECK (book IN ('ТЗ','ОП'));
-- id групам ОП — свої, далеко за групами ТЗ: повна база заводить групи ТЗ з id від 1.
INSERT OR IGNORE INTO nomen_group(id, code, name, sort, book) VALUES
  (901, 'ОП.1', 'Одноразовий посуд', 901, 'ОП'),
  (902, 'ОП.2', 'Серветки', 902, 'ОП'),
  (903, 'ОП.3', 'Миючі засоби', 903, 'ОП'),
  (904, 'ОП.4', 'Господарчі товари', 904, 'ОП');

-- «Дободач» книги ОП: скільки добових видач покриває одиниця позиції.
ALTER TABLE nomen ADD COLUMN per_ration REAL;

-- Де документ у ФЕС: передали реєстром, підписали, провели. Модель спільна з документами
-- закупівель (ВН, акти вводу) — там ті самі п'ять станів.
CREATE TABLE document_fes (
  document_id INTEGER PRIMARY KEY REFERENCES document(id) ON DELETE CASCADE,
  status TEXT NOT NULL CHECK (status IN ('немає витяга','на підписі','їде на ФЕС','проведено','переробка')),
  changed_on TEXT,
  register TEXT,
  fes_ref TEXT,
  note TEXT
) STRICT;

-- Поля документа з книги ОП, яких у документів ТЗ не було, і графа звіту 2/прод, обрана
-- людиною замість тієї, що дає правило.
CREATE TABLE document_extra (
  document_id INTEGER PRIMARY KEY REFERENCES document(id) ON DELETE CASCADE,
  report TEXT,
  order_ref TEXT,
  scan TEXT,
  form2_col INTEGER CHECK (form2_col IN (12,13,14,16,17))
) STRICT;

CREATE TABLE report_line_new (
  id INTEGER PRIMARY KEY,
  form_id INTEGER NOT NULL REFERENCES report_form(id),
  code TEXT,
  name TEXT NOT NULL,
  section TEXT,
  sort INTEGER NOT NULL DEFAULT 0,
  row_no INTEGER,
  uom TEXT,
  is_header INTEGER NOT NULL DEFAULT 0 CHECK (is_header IN (0,1))
) STRICT;
  SELECT id, form_id, code, name, section, sort FROM report_line;
DROP TABLE report_line;
ALTER TABLE report_line_new RENAME TO report_line;
CREATE UNIQUE INDEX ux_report_line_name ON report_line(form_id, name) WHERE row_no IS NULL;
CREATE UNIQUE INDEX ux_report_line_row ON report_line(form_id, row_no) WHERE row_no IS NOT NULL;

-- Прив'язка коду до рядка форми: множник переводить одиницю позиції в одиницю рядка
-- («тис. шт» → шт = 1000); хто й коли перевірив прив'язку («уточнити» — ще ні).
CREATE TABLE nomen_report_line_new (
  nomen_id INTEGER NOT NULL REFERENCES nomen(id),
  report_line_id INTEGER NOT NULL REFERENCES report_line(id),
  factor REAL NOT NULL DEFAULT 1 CHECK (factor > 0),
  checked_by TEXT,
  checked_on TEXT,
  PRIMARY KEY (nomen_id, report_line_id)
) STRICT;
  SELECT nomen_id, report_line_id FROM nomen_report_line;
DROP TABLE nomen_report_line;
ALTER TABLE nomen_report_line_new RENAME TO nomen_report_line;

-- Код, який свідомо не йде у форму (господарчі товари поза 2/прод, майно для 3/прод).
CREATE TABLE nomen_form_skip (
  nomen_id INTEGER NOT NULL REFERENCES nomen(id),
  form_id INTEGER NOT NULL REFERENCES report_form(id),
  reason TEXT,
  PRIMARY KEY (nomen_id, form_id)
) STRICT;

-- Зданий звіт 2/прод: графи по рядках бланка, як їх подали (гр.8 нового звіту = гр.18 зданого).
CREATE TABLE form2_submitted (
  year INTEGER NOT NULL,
  row_no INTEGER NOT NULL,
  col INTEGER NOT NULL CHECK (col BETWEEN 5 AND 29),
  value_milli INTEGER NOT NULL,
  PRIMARY KEY (year, row_no, col)
) STRICT;

-- Графи, які вписує людина (потреба, категорії, «підлягає списанню», позичка).
CREATE TABLE form2_cell (
  year INTEGER NOT NULL,
  row_no INTEGER NOT NULL,
  col INTEGER NOT NULL CHECK (col BETWEEN 5 AND 29),
  value_milli INTEGER NOT NULL,
  PRIMARY KEY (year, row_no, col)
) STRICT;

-- Записки: поправки помилок минулих звітів у гр.14 (+) і гр.17 (−) з пояснювальною.
CREATE TABLE form2_note (
  id INTEGER PRIMARY KEY,
  year INTEGER NOT NULL,
  row_no INTEGER NOT NULL,
  col INTEGER NOT NULL CHECK (col IN (14,17)),
  qty_milli INTEGER NOT NULL CHECK (qty_milli > 0),
  reason TEXT NOT NULL,
  number TEXT,
  doc_date TEXT
) STRICT;

-- Позиція звіту ФЕС (код ФЕС + ціна партії) → код обліку, для звірки з ФЕС; без коду —
-- позиція ФЕС не з книги ОП (звірка її пропускає, а не питає щоразу).
CREATE TABLE fes_item_map (
  fes_code TEXT NOT NULL,
  price_kop INTEGER NOT NULL,
  nomen_id INTEGER REFERENCES nomen(id),
  PRIMARY KEY (fes_code, price_kop)
) STRICT;

-- 2/Прод: перелік бланка (згенеровано build/make_form2_seed.py — між маркерами не правити).
-- ПЕРЕЛІК 2/ПРОД: ПОЧАТОК
INSERT OR IGNORE INTO report_form(code, name) VALUES('2/Прод', 'Звіт-заявка на посуд, столові прибори, кухонний інвентар і тару');
-- Рядків 1826: заголовків 53, позицій 1773.
-- Старий перелік 2/Прод (до схеми 26): зв'язки — на рядки бланка з тією самою назвою.
INSERT OR IGNORE INTO nomen_report_line(nomen_id, report_line_id) SELECT m.nomen_id, (SELECT n.id FROM report_line n WHERE n.form_id = (SELECT id FROM report_form WHERE code = '2/Прод') AND n.row_no IS NOT NULL AND n.name = o.name ORDER BY n.row_no LIMIT 1) FROM nomen_report_line m JOIN report_line o ON o.id = m.report_line_id WHERE o.form_id = (SELECT id FROM report_form WHERE code = '2/Прод') AND o.row_no IS NULL AND (SELECT n.id FROM report_line n WHERE n.form_id = (SELECT id FROM report_form WHERE code = '2/Прод') AND n.row_no IS NOT NULL AND n.name = o.name ORDER BY n.row_no LIMIT 1) IS NOT NULL;
DELETE FROM nomen_report_line WHERE report_line_id IN (SELECT id FROM report_line WHERE form_id = (SELECT id FROM report_form WHERE code = '2/Прод') AND row_no IS NULL);
UPDATE norm SET report_line_id = (SELECT (SELECT n.id FROM report_line n WHERE n.form_id = (SELECT id FROM report_form WHERE code = '2/Прод') AND n.row_no IS NOT NULL AND n.name = o.name ORDER BY n.row_no LIMIT 1) FROM report_line o WHERE o.id = norm.report_line_id) WHERE report_line_id IN (SELECT o.id FROM report_line o WHERE o.form_id = (SELECT id FROM report_form WHERE code = '2/Прод') AND o.row_no IS NULL AND (SELECT n.id FROM report_line n WHERE n.form_id = (SELECT id FROM report_form WHERE code = '2/Прод') AND n.row_no IS NOT NULL AND n.name = o.name ORDER BY n.row_no LIMIT 1) IS NOT NULL);
DELETE FROM report_line WHERE form_id = (SELECT id FROM report_form WHERE code = '2/Прод') AND row_no IS NULL AND id NOT IN (SELECT report_line_id FROM norm WHERE report_line_id IS NOT NULL);
-- ПЕРЕЛІК 2/ПРОД: КІНЕЦЬ

COMMIT;
PRAGMA foreign_keys = ON;
